<?php
if (!defined('WP_CLI') || !WP_CLI || wp_get_environment_type()!=='local' || getenv('ATLAS_TEST_DB')!=='atlas_integration') throw new RuntimeException('Isolated local fixture required.');
if (!defined('ATLAS_TEST_CLOCK')) define('ATLAS_TEST_CLOCK',true);
use Atlas\Core\DB;
use Atlas\Core\Records;
use Atlas\Core\Offers;
use Atlas\Core\Booking;
use Atlas\Core\VerifiedPayment;
use Atlas\Core\Jobs;
global $wpdb;
$passed=0;$failed=0;
$check=static function($ok,$text) use(&$passed,&$failed){if($ok){$passed++;echo "PASS $text\n";}else{$failed++;echo "FAIL $text\n";}};
$admin=(int)get_users(array('role'=>'administrator','fields'=>'ID','number'=>1))[0];$suffix=strtolower(wp_generate_password(10,false,false));
$customer=wp_insert_user(array('user_login'=>'notice_'.$suffix,'user_pass'=>wp_generate_password(32),'user_email'=>'notice_'.$suffix.'@example.test','role'=>'subscriber'));
$other=wp_insert_user(array('user_login'=>'notice_other_'.$suffix,'user_pass'=>wp_generate_password(32),'user_email'=>'notice_other_'.$suffix.'@example.test','role'=>'subscriber'));
if(is_wp_error($customer)||is_wp_error($other)) WP_CLI::error('User fixtures failed.');
$request=static function($method,$route,$body=null,$nonce=true){$r=new WP_REST_Request($method,$route);if($nonce)$r->set_header('X-WP-Nonce',wp_create_nonce('wp_rest'));if($body!==null){$r->set_header('Content-Type','application/json');$r->set_body(wp_json_encode($body));}return $r;};
wp_set_current_user($admin);
$offer=Offers::save(0,array('kind'=>'event','org_id'=>0,'title_en'=>'Fictional notification fixture','title_fa'=>'','description_en'=>'','description_fa'=>'','registration_open_at'=>'2001-01-01T00:00:00Z','registration_close_at'=>'2001-01-02T00:00:00Z','timezone'=>'UTC','capacity'=>3,'amount_irr'=>1000000,'mode'=>'local','status'=>'published','product_id'=>0),$admin);
DB::set_test_now('2001-01-01T09:00:00Z');wp_set_current_user($customer);
$hold=Booking::hold($offer,1,1,$customer,'notice-hold-'.$suffix);if(!is_array($hold))WP_CLI::error('Booking fixture failed.');
$case=Records::create('support_case',array('state'=>'new','category'=>'general','subject'=>'Fictional pagination','message'=>'Fictional opening message'),$customer);if(is_wp_error($case))WP_CLI::error('Support fixture failed.');
for($i=0;$i<5;$i++)$wpdb->insert(Atlas_Support_Workflow::table(),array('id'=>wp_generate_uuid4(),'case_id'=>$case['id'],'author_id'=>$i%2?$admin:$customer,'internal_note'=>$i%2?1:0,'body'=>$i%2?'Fictional private note':'Shared page '.$i,'idem_key'=>'page-'.$suffix.'-'.$i,'request_hash'=>hash('sha256',(string)$i),'created_at'=>'2001-01-01 09:00:0'.$i.'.000000'));
$firstReq=$request('GET','/agency/v1/support-cases/'.$case['id'].'/messages');$firstReq->set_param('limit',2);$first=rest_do_request($firstReq);
$nextReq=clone $firstReq;$nextReq->set_param('page',2);$next=rest_do_request($nextReq);$a=$first->get_data();$b=$next->get_data();
$check($first->get_status()===200 && count($a['messages'])===2 && $a['pagination']['has_more'] && count($b['messages'])===1 && !$b['pagination']['has_more'],'support pages reach every shared reply without leaking internal-note counts');
$ids=array_merge(array_column($a['messages'],'id'),array_column($b['messages'],'id'));
$check(count(array_unique($ids))===3 && !str_contains(wp_json_encode(array($a,$b)),'Fictional private note'),'support pagination has no duplicate rows or private note disclosure');
$bad=clone $firstReq;$bad->set_param('page',array(1));$check(rest_do_request($bad)->get_status()===422,'malformed pagination is rejected without scalar coercion');
wp_set_current_user($other);$check(rest_do_request($firstReq)->get_status()===404,'another account cannot paginate a private conversation');
wp_set_current_user($admin);$all=clone $firstReq;$all->set_param('limit',10);$check(count(rest_do_request($all)->get_data()['messages'])===5,'agency conversation includes authorized private notes');
$template=array('event_type'=>'booking.held','locale'=>'en','body'=>'Fictional account update: {reference}','reason'=>'Automated local fixture review only','approve'=>true);
wp_set_current_user($customer);
$check(rest_do_request($request('POST','/agency/v1/notification-operations/templates',$template))->get_status()===403,'customer cannot approve notification templates');
$check(rest_do_request($request('GET','/agency/v1/notifications',null,false))->get_status()===403,'notification API requires an explicit authenticated nonce');
wp_set_current_user($admin);$saved=rest_do_request($request('POST','/agency/v1/notification-operations/templates',$template));
$check($saved->get_status()===200 && $saved->get_data()['state']==='approved','agency records a versioned local fixture template review');
$event=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('outbox').' WHERE event_type=%s AND aggregate_id=%s','booking.held',$hold['booking_id']),ARRAY_A);
$sent=Atlas_Notifications::deliver(null,$event);$replay=Atlas_Notifications::deliver(null,$event);
$count=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.Atlas_Notifications::table().' WHERE event_id=%s',$event['id']));
$check($sent===true && $replay===true && $count===1,'committed outbox replay records exactly one logical in-account notice');
wp_set_current_user($customer);$list=rest_do_request($request('GET','/agency/v1/notifications'));$items=$list->get_data()['items'];
$notice=$items[0]??array();$check(count($items)===1 && !str_contains(wp_json_encode($items),'provider_ref') && $list->get_headers()['Cache-Control']==='private, no-store','owner notice projection excludes transport secrets and prevents shared caching');
wp_set_current_user($other);$foreign=rest_do_request($request('POST','/agency/v1/notifications/'.($notice['id']??'missing').'/read',array()));
$check($foreign->get_status()===404 && count(rest_do_request($request('GET','/agency/v1/notifications'))->get_data()['items'])===0,'notice reference cannot expose or change another recipient account');
wp_set_current_user($customer);$read=rest_do_request($request('POST','/agency/v1/notifications/'.$notice['id'].'/read',array()));
$check($read->get_status()===200 && $read->get_data()['state']==='read','owner can acknowledge an in-account notice');
$wpdb->update(DB::table('outbox'),array('status'=>'delivered'),array('id'=>$event['id']));
DB::emit('booking.exception',$hold['booking_id']);$failureEvent=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('outbox').' WHERE event_type=%s AND aggregate_id=%s ORDER BY created_at,id DESC LIMIT 1','booking.exception',$hold['booking_id']),ARRAY_A);
// Other fictional fixtures do not influence this focused queue test.
$unrelated=static function($ok,$event) use($failureEvent){return $event['id']===$failureEvent['id']?$ok:true;};add_filter('atlas_core_deliver_outbox',$unrelated,1,2);
try {
    for($i=0;$i<5;$i++) {
        $wpdb->update(DB::table('outbox'),array('available_at'=>DB::now()),array('id'=>$failureEvent['id']));Jobs::dispatch_outbox();
    }
} finally {remove_filter('atlas_core_deliver_outbox',$unrelated,1);}
$status=$wpdb->get_row($wpdb->prepare('SELECT status,attempts FROM '.DB::table('outbox').' WHERE id=%s',$failureEvent['id']));
$booking=Booking::get($hold['booking_id'],$customer);
$check($status && $status->status==='failed' && (int)$status->attempts===5 && $booking['status']==='held' && $booking['payment_status']==='unverified','missing approved template reaches bounded failed queue without changing booking or money');
wp_set_current_user($admin);$retry=rest_do_request($request('POST','/agency/v1/notification-operations/retry',array('id'=>$failureEvent['id'],'reason'=>'Automated fixture retry review')));
$check($retry->get_status()===200 && $retry->get_data()['state']==='pending','agency can audit a deliberate retry after reviewing a failed event');
wp_set_current_user($customer);$_GET['lang']='fa';$check(str_contains(Atlas_Notifications::panel(),'اعلان‌های حساب'),'Persian account notification controls render');unset($_GET['lang']);
$late=Booking::hold($offer,1,1,$customer,'notice-late-'.$suffix);
if (is_wp_error($late)) WP_CLI::error('Late payment fixture hold failed.');
DB::set_test_now('2001-01-01T09:11:00Z');
Booking::expire($late['hold_id']);
$verified=Booking::verify($late['booking_id'],VerifiedPayment::from_adapter('local_simulator','fictional-late-'.$suffix,1000000));
if (is_wp_error($verified)) WP_CLI::error('Late payment fixture verification failed.');
$paymentEvent=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('outbox').' WHERE event_type=%s AND aggregate_id=%s','payment.exception',$verified['payment_id']),ARRAY_A);
apply_filters('atlas_core_deliver_outbox',null,$paymentEvent);
apply_filters('atlas_core_deliver_outbox',null,$paymentEvent);
$caseIds=$wpdb->get_col($wpdb->prepare('SELECT case_id FROM '.$wpdb->prefix.'atlas_support_payment_cases WHERE payment_id=%s',$verified['payment_id']));
$paymentCase=Records::get('support_case',$caseIds[0]??'',(int)$customer);
$check(count($caseIds)===1 && !is_wp_error($paymentCase) && $paymentCase['fields']['priority']==='urgent' && $paymentCase['fields']['booking_id']===$late['booking_id'] && !str_contains(wp_json_encode($paymentCase),'fictional-late-'.$suffix),'verified late payment automatically opens one private payment review case with a masked reference');
$booking=Booking::get($late['booking_id'],(int)$customer);
$check($booking['status']==='exception' && $booking['payment_status']==='verified' && $wpdb->get_var($wpdb->prepare('SELECT state FROM '.DB::table('holds').' WHERE id=%s',$late['hold_id']))==='released','review-case processing leaves payment, admission and released inventory unchanged');
wp_set_current_user($other);
$check(is_wp_error(Records::get('support_case',$caseIds[0]??'',(int)$other)),'another customer cannot see the automatically opened payment case');
$mine=rest_do_request($request('GET','/agency/v1/support-cases'));
$queueReq=$request('GET','/agency/v1/support-cases');$queueReq->set_param('scope','queue');
$check($mine->get_status()===200 && !$mine->get_data()['items'] && rest_do_request($queueReq)->get_status()===403,'case listing excludes other owners and restricts the agency queue');
wp_set_current_user($admin);$queueReq=$request('GET','/agency/v1/support-cases');$queueReq->set_param('scope','queue');$queue=rest_do_request($queueReq);
$check($queue->get_status()===200 && $queue->get_headers()['Cache-Control']==='private, no-store' && count($queue->get_data()['items'])<=20,'authorized agency queue has bounded private pages');
$oldBeat=get_option('atlas_core_worker_heartbeat',null);
$heartbeat=Jobs::run();
$health=rest_do_request($request('GET','/agency/v1/operations-health'));
$check($health->get_status()===200 && $health->get_data()['scheduler_heartbeat_utc']===$heartbeat['finished_at'] && $health->get_headers()['Cache-Control']==='private, no-store' && !str_contains(wp_json_encode($health->get_data()),$late['booking_id']),'worker heartbeat and backlog measurements are scoped aggregates without booking identifiers');
if ($oldBeat===null) delete_option('atlas_core_worker_heartbeat'); else update_option('atlas_core_worker_heartbeat',$oldBeat,false);
wp_set_current_user($other);
$check(rest_do_request($request('GET','/agency/v1/operations-health'))->get_status()===403,'customer cannot inspect worker and settlement readiness signals');
DB::set_test_now(null);
echo "Notification/support checks: $passed passed, $failed failed\n";
if($failed)WP_CLI::error('Notification/support regression failed.');WP_CLI::success('Scoped in-account notification and support workflows verified; no email or SMS sent.');
